style.css:
@-moz-document domain("outlook.office.com"), domain("outlook.live.com"), domain("outlook.office365.com") {
:root {
        --pink-primary: #d81b60;
        --pink-header: #c2185b;
        --pink-bg-light: #fff0f5;
        --pink-selection: #f8bbd0;
        --pink-border: #f48fb1;
        --pink-text: #880e4f;
    }

    /* -------------------------------------------------------------
       1. TOP HEADER BAR WITH WHITE FLORAL GRAPHICS
       ------------------------------------------------------------- */
    #O365_MainHeader,
    header[role="banner"],
    div[data-app-section="Header"] {
        background-color: var(--pink-header) !important;
        /* Inline SVG background pattern of white doodle flowers */
        background-image: url('data:image/svg+xml;utf8,<svg xmlns="[w3.org](http://www.w3.org/2000/svg)" width="120" height="48" viewBox="0 0 120 48" fill="none" stroke="rgba(255,255,255,0.4)" stroke-width="1.5" stroke-linecap="round"><path d="M20 15c2-4 7-4 9 0 4-2 7 2 5 6 4 2 2 7-2 9 0 4-5 5-8 2-4 2-7-2-5-6-4-2-2-7 2-9z"/><circle cx="24.5" cy="20" r="2.5"/><path d="M80 10c1.5-3 5-3 6.5 0 3-1.5 5 1.5 3.5 4.5 3 1.5 1.5 5-1.5 6.5 0 3-3.5 3.5-5.5 1.5-3 1.5-5-1.5-3.5-4.5-3-1.5-1.5-5 1.5-6.5z"/><circle cx="83.2" cy="14" r="1.8"/></svg>') !important;
        background-repeat: repeat-x !important;
        background-position: center !important;
    }

    /* Header text & search bar adjustments */
    #O365_MainHeader *,
    header[role="banner"] * {
        color: #ffffff !important;
    }

    div[role="search"] input {
        background-color: rgba(255, 255, 255, 0.25) !important;
        color: #ffffff !important;
        border-radius: 18px !important;
    }

    div[role="search"] input::placeholder {
        color: rgba(255, 255, 255, 0.8) !important;
    }

    /* -------------------------------------------------------------
       2. LEFT NAVIGATION & FOLDER PANE
       ------------------------------------------------------------- */
    div[role="navigation"],
    #LeftHideablePane,
    div[data-app-section="NavigationPane"] {
        background-color: var(--pink-bg-light) !important;
        border-right: 1px solid var(--pink-border) !important;
    }

    /* Folder list text & selection */
    div[role="treeitem"]:hover,
    div[role="navigation"] button:hover {
        background-color: rgba(216, 27, 96, 0.1) !important;
        border-radius: 8px !important;
    }

    /* -------------------------------------------------------------
       3. MESSAGE LIST (MIDDLE PANE)
       ------------------------------------------------------------- */
    div[data-app-section="MessageList"] {
        background-color: #ffffff !important;
    }

    /* Selected email in list */
    div[role="option"][aria-selected="true"],
    div[aria-selected="true"] > div {
        background-color: var(--pink-selection) !important;
        border-radius: 12px !important;
    }

    /* Unread/Selected email text highlight */
    div[role="option"][aria-selected="true"] * {
        color: var(--pink-text) !important;
    }

    /* -------------------------------------------------------------
       4. READING PANE WITH SIDE FLORAL DOODLES
       ------------------------------------------------------------- */
    #ReadingPaneContainerId,
    div[data-app-section="ConversationReadingPane"] {
        background-color: #fff9fb !important;
        /* Delicate pink line-art flowers running down left and right sides */
        background-image: url('data:image/svg+xml;utf8,<svg xmlns="[w3.org](http://www.w3.org/2000/svg)" width="60" height="300" viewBox="0 0 60 300" fill="none" stroke="%23f48fb1" stroke-width="1.2" stroke-linecap="round"><path d="M15 40c3-6 10-6 13 0 6-3 10 3 7 9 6 3 3 10-3 13 0 6-7 7-12 3-6 3-10-3-7-9-6-3-3-10 3-13z"/><circle cx="21.5" cy="48" r="3"/><path d="M21.5 61c-2 20-5 40 5 70"/><path d="M20 85c-6-4-10-2-12 2"/><path d="M23 100c6-3 10-1 11 3"/><path d="M35 200c2-4 7-4 9 0 4-2 7 2 5 6 4 2 2 7-2 9 0 4-5 5-8 2-4 2-7-2-5-6-4-2-2-7 2-9z"/><circle cx="39.5" cy="205" r="2"/></svg>'),
                          url('data:image/svg+xml;utf8,<svg xmlns="[w3.org](http://www.w3.org/2000/svg)" width="60" height="300" viewBox="0 0 60 300" fill="none" stroke="%23f48fb1" stroke-width="1.2" stroke-linecap="round"><path d="M30 80c3-6 10-6 13 0 6-3 10 3 7 9 6 3 3 10-3 13 0 6-7 7-12 3-6 3-10-3-7-9-6-3-3-10 3-13z"/><circle cx="36.5" cy="88" r="3"/><path d="M36.5 101c-2 20-5 40 5 70"/><path d="M20 230c2-4 7-4 9 0 4-2 7 2 5 6 4 2 2 7-2 9 0 4-5 5-8 2-4 2-7-2-5-6-4-2-2-7 2-9z"/><circle cx="24.5" cy="235" r="2"/></svg>') !important;
        background-repeat: repeat-y, repeat-y !important;
        background-position: left top, right top !important;
    }

    /* Inner email card container */
    div[role="main"] article,
    div[role="main"] .is-expanded {
        background-color: rgba(255, 255, 255, 0.92) !important;
        border-radius: 12px !important;
        border: 1px solid var(--pink-border) !important;
    }

    /* -------------------------------------------------------------
       5. BUTTONS & UI ACCENTS
       ------------------------------------------------------------- */
    /* Primary buttons (New Mail, Action buttons) */
    button[title*="New mail"],
    button[aria-label*="New mail"],
    .ms-Button--primary,
    button[class*="primary"] {
        background-color: var(--pink-primary) !important;
        border-color: var(--pink-primary) !important;
        color: #ffffff !important;
        border-radius: 20px !important;
        font-weight: 600 !important;
    }

    button[title*="New mail"]:hover,
    .ms-Button--primary:hover {
        background-color: var(--pink-header) !important;
    }

    /* Checkboxes & Icons */
    i[data-icon-name="CheckMark"],
    i[data-icon-name="SingleBookmark"] {
        color: var(--pink-primary) !important;
    }

    /* Custom Pink Scrollbars */
    ::-webkit-scrollbar {
        width: 8px;
        height: 8px;
    }
    ::-webkit-scrollbar-track {
        background: var(--pink-bg-light);
    }
    ::-webkit-scrollbar-thumb {
        background: var(--pink-border);
        border-radius: 4px;
    }
    ::-webkit-scrollbar-thumb:hover {
        background: var(--pink-primary);
    }
}
